INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(42511, 'Job 15:14', 'Job', 15, 14, 'بنى آدم څۀ وى، چې هغه صفا شى؟ او چې د ښځې نه پېدا شى، نو هغه صادق کېدے شى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_14.mp3', '', 1761754199, 1761754199),
(42512, 'Job 15:15', 'Job', 15, 15, 'ګوره، خُدائ پاک په خپلو فرښتو باندې هم اعتبار نۀ کوى، او د هغۀ په نظر کښې آسمانونه هم صفا نۀ دى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_15.mp3', '', 1761754199, 1761754199),
(42513, 'Job 15:16', 'Job', 15, 16, 'نو بيا به بنى آدم نور هم ګنده او ګناه ګار وى، څوک چې هر وخت په ګناه کښې آخته وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_16.mp3', '', 1761754199, 1761754199),
(42514, 'Job 15:17', 'Job', 15, 17, 'کۀ تۀ زما خبرې ته غوږ کېږدې، نو زۀ به تا ته وښايم، او چې ما څۀ ليدلى وى نو زۀ به درته د هغې بيان وکړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_17.mp3', '', 1761754199, 1761754199),
(42515, 'Job 15:18', 'Job', 15, 18, 'څۀ چې هوښيارانو وئيلى دى، نو د هغوئ پلار نيکۀ دا خبرې د هغوئ نه پټى نۀ دې ساتلې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_18.mp3', '', 1761754199, 1761754199),
(42516, 'Job 15:19', 'Job', 15, 19, 'کومو مشرانو له چې ډېره موده مخکښې دا مُلک ورکړے شو او چې په هغه وخت کښې لا غېر قومونه نۀ وو راغلى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_19.mp3', '', 1761754199, 1761754199),
(42517, 'Job 15:20', 'Job', 15, 20, 'بدعمله خلق ټول عمر په خپل درد کړيږى، د تکليف کالونه په ظالمانو باندې راجمع شوى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_20.mp3', '', 1761754199, 1761754199),
(42518, 'Job 15:21', 'Job', 15, 21, 'د هغوئ په غوږُونو کښې يروونکى آوازونه دى، د امن په وخت کښې به په هغوئ باندې تباهى راشى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_21.mp3', '', 1761754199, 1761754199),
(42519, 'Job 15:22', 'Job', 15, 22, 'هغوئ تيارۀ ته د تلو همت نۀ شى کولے، د هغوئ ژوند هر وخت په خطره کښې وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_22.mp3', '', 1761754199, 1761754199),
(42520, 'Job 15:23', 'Job', 15, 23, 'ټپوسان انتظار کوى چې د هغوئ غوښې وخورى، او تباهى د هغوئ سر له راغلې ده،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_23.mp3', '', 1761754199, 1761754199),
(42521, 'Job 15:24', 'Job', 15, 24, 'پرېشانى او تکليف هغوئ ويروى، او دا څيزونه په هغوئ باندې غالِب شى، داسې لکه چې يو بادشاه د جنګ دپاره تيار شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_24.mp3', '', 1761754199, 1761754199),
(42522, 'Job 15:25', 'Job', 15, 25, 'ځکه چې هغوئ خپل لاسونه د خُدائ پاک خِلاف اوچت کړل، او هغوئ د قادر خُدائ نه بغاوت وکړو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_25.mp3', '', 1761754199, 1761754199),
(42523, 'Job 15:26', 'Job', 15, 26, 'هغوئ د هغۀ خِلاف د سرکشۍ سره حمله کوى، او يو غټ ډال ورسره وى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_26.mp3', '', 1761754199, 1761754199),
(42524, 'Job 15:27', 'Job', 15, 27, 'دا بدعمله خلق درانۀ او مالدار دى، د هغوئ څټونه په وازګه باندې غټ شوى دى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_27.mp3', '', 1761754199, 1761754199),
(42525, 'Job 15:28', 'Job', 15, 28, 'هغوئ به په تباه شوى ښارونو کښې ژوند تېروى، او په داسې کورَنو کښې چې په هغې کښې هيڅ څوک هم نۀ اوسيږى، داسې کورونه چې په راغورزېدو بدل وى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_28.mp3', '', 1761754199, 1761754199),
(42526, 'Job 15:29', 'Job', 15, 29, 'هغوئ به نۀ مالداره کيږى او د هغوئ مال دولت به نۀ پاتې کيږى، او هغوئ به د زمکې د مخ نه ورک شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_29.mp3', '', 1761754199, 1761754199),
(42527, 'Job 15:30', 'Job', 15, 30, 'هغوئ به د تيارې نه ونۀ تښتى، لمبې به د هغوئ څانګې وسوزوى، او د هغوئ ژوند به داسې ختم شى لکه چې هوا د ګلونو غوټۍ ختموى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_30.mp3', '', 1761754199, 1761754199),
(42528, 'Job 15:31', 'Job', 15, 31, 'هغوئ دې نور خپل ځان په فانى مالدارۍ باندې نۀ دوکه کوى، ځکه چې هغوئ به تش لاس پاتې شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_31.mp3', '', 1761754199, 1761754199),
(42529, 'Job 15:32', 'Job', 15, 32, 'د ونو په شان، چې کله دا ښې شنې وى نو ووهلے شى، او د دې څانګې بيا هيڅکله شنې نۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_32.mp3', '', 1761754199, 1761754199),
(42530, 'Job 15:33', 'Job', 15, 33, 'او د هغوئ انګور چې لا کچه وى نو وبه غورزيږى، او د زيتُونو د ونو په شان به خپلې د ګلونو غوټۍ ضائع کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_33.mp3', '', 1761754199, 1761754199),
(42531, 'Job 15:34', 'Job', 15, 34, 'ځکه چې د خُدائ پاک نه د منکرو خلقو اولاد به نۀ وى، او څوک چې د رشوت سره مينه کوى نو اور به د هغوئ کورونه سوزوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_34.mp3', '', 1761754199, 1761754199),
(42532, 'Job 15:35', 'Job', 15, 35, 'داسې خلق نورو ته د نقصان رسولو په سوچ کښې وى، هغوئ شېطانى کوى او د هغوئ زړونه د دوکې نه ډک وى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job15_verse_35.mp3', '', 1761754199, 1761754199),
(42533, 'Esther 1:3', 'Esther', 1, 3, 'هغه د خپلې پاچاهۍ په درېم کال خپلو مامورینو او درباریانو ته مېلمستیا جوړه کړه. په مېلمستیا کې د فارس او ماد د لښکرو قوماندانان، مشران او والیان حاضر وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther1_verse_3.mp3', '', 1761754199, 1761754199),
(42534, 'Esther 1:4', 'Esther', 1, 4, 'د پوره شپږو میاشتو دپاره پاچا د خپلې پاچاهۍ زیاته شتمني، شان او شوکت او خپله شاهانه لویي نندارې ته وړاندې کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther1_verse_4.mp3', '', 1761754199, 1761754199),
(42535, 'Esther 1:5', 'Esther', 1, 5, 'وروسته له هغې پاچا ټولو خلکو ته که شتمن وو یا غریب، د شوش په بالاحصار کې د شاهي ماڼۍ د باغ په حوېلۍ کې مېلمستیا ورکړه او پوره اووه ورځې دې مېلمستیا دوام وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther1_verse_5.mp3', '', 1761754199, 1761754199),
(42536, 'Esther 1:6', 'Esther', 1, 6, 'حوېلۍ په اسماني او د سپین کتان په پردو باندې ښکلې شوې وه چې په بانجاني ښه کتاني رسیو باندې تړل شوې وې او د سپینو زرو په هغو کړیو کې ځای په ځای شوې وې چې د مرمرو په ستنو باندې ځوړندې وې. هغه تختونه چې د سرو او سپینو زرو څخه جوړ شوي وو، په هغې حوېلۍ کې چې په سپینو مرمرو، سور بخنو تیږو، صدف او فیروزې باندې فرش شوی ؤ، ایښودل شوي وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther1_verse_6.mp3', '', 1761754199, 1761754199),
(42537, 'Esther 1:7', 'Esther', 1, 7, 'شراب یې د سرو زرو په پیالو کې ورکول او هرې پیالې یې د بلې پیالې نه فرق درلود. پاچا خلکو ته د شاهانه شرابو په ورکولو کې ډېر سخي ؤ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther1_verse_7.mp3', '', 1761754199, 1761754199),
(42538, 'Esther 1:8', 'Esther', 1, 8, 'او د څښلو دپاره کومه اندازه نه وه ټاکل شوې. پاچا د ماڼۍ ټولو خدمتګارانو ته حکم کړی ؤ، هرڅوک چې څومره وغواړي هغومره څښلی شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther1_verse_8.mp3', '', 1761754199, 1761754199),
(42539, 'Esther 1:9', 'Esther', 1, 9, 'په همدې وخت کې وشتي ملکې هم د خشایار پاچا په شاهي ماڼۍ کې ښځو ته مېلمستیا جوړه کړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther1_verse_9.mp3', '', 1761754199, 1761754199),
(42540, 'Esther 1:10', 'Esther', 1, 10, 'په اوومه ورځ کله چې خشایار پاچا په شرابو باندې مست شوی ؤ اووه خصي شوي سړي یعنې مهومان، بزتا، حربونا، بګتا، ابغتا، زاتر او کرکس چې د هغه خدمت یې کاوه، راوغوښتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther1_verse_10.mp3', '', 1761754199, 1761754199),
(42541, 'Esther 1:11', 'Esther', 1, 11, 'پاچا هغوی ته امر وکړ چې ملکه وشتي د ده حضور ته راولي چې شاهي تاج یې په سر وي. ملکه یوه ښکلې ښځه وه او پاچا غوښتل چې د هغې ښکلا خپلو مامورینو او ټولو مېلمنو ته وښایي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther1_verse_11.mp3', '', 1761754199, 1761754199),
(42542, 'Esther 1:12', 'Esther', 1, 12, 'خو کله چې خدمتګارانو د پاچا فرمان وشتي ملکې ته ورساوه، هغې د راتللو څخه انکار وکړ. پاچا په هغې باندې ډېر په قهر شو او له قهره تک سور شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther1_verse_12.mp3', '', 1761754199, 1761754199),
(42543, 'Esther 1:13', 'Esther', 1, 13, 'پاچا عادت درلود چې د قانون د عملي کولو په اړه د ماهرو مشاورانو نظر ولري. نو ځکه یې خپل مشاوران راوغوښتل ترڅو د هغوی څخه پوښتنه وکړي چې څه باید وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther1_verse_13.mp3', '', 1761754199, 1761754199),
(42544, 'Esther 1:14', 'Esther', 1, 14, 'هغه کسان چې پاچا به زیات وخت ورسره مشوره کوله دا وو: کرشنا، شیتار، ادماتا، ترشیش، مرس، مرسنا او مموکان. دا د پارس او ماد په پاچاهۍ کې اووه لوړ رتبه مامورین وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther1_verse_14.mp3', '', 1761754199, 1761754199),
(42545, 'Esther 1:15', 'Esther', 1, 15, 'پاچا د دغو مامورینو څخه پوښتنه وکړه: «د قانون سره سم باید د وشتي ملکې سره څه وشي؟ ځکه چې هغې زما یعنې د خشایار پاچا حکم نه دی منلی، هغه حکم چې د خدمتګارانو په لاس مې هغې ته استولی ؤ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther1_verse_15.mp3', '', 1761754199, 1761754199),
(42546, 'Esther 1:16', 'Esther', 1, 16, 'بیا مموکان د پاچا او مامورینو په حضور کې په ځواب کې وویل: «وشتي ملکې نه یوازې د خشایار پاچا په وړاندې بلکې د ټولو مامورینو او د پاچا د ټولو ولایتونو د ټولو قومونو په وړاندې هم سپکاوی کړی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther1_verse_16.mp3', '', 1761754199, 1761754199),
(42547, 'Esther 1:17', 'Esther', 1, 17, 'د ملکې د سپکاوي خبره به د ټولو ښځو غوږونو ته ورسیږي او هغوی به دې ته وهڅوي چې د خپلو مېړونو سره سپک چلند وکړي. هغوی به وایي: ‹خشایار پاچا امر وکړ چې وشتي ملکه دې د پاچا حضور ته راوستل شي، خو هغه رانغله.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther1_verse_17.mp3', '', 1761754199, 1761754199),
(42548, 'Esther 1:18', 'Esther', 1, 18, 'کله چې د فارس او ماد د مامورینو ښځې د ملکې د چلند په هکله واوري، نو دوی به په همدې ورځ خپلو مېړونو ته په دې هکله ووایي. نو په هرځای کې به ښځې د خپلو مېړونو درناوی نه کوي او مېړونه به په خپلو ښځو باندې په قهر وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther1_verse_18.mp3', '', 1761754199, 1761754199),
(42549, 'Esther 1:19', 'Esther', 1, 19, 'که چېرې ستاسو د اعلیحضرت خوښه وي چې یو شاهي حکم جاري کړئ چې وشتي دې بیا هېڅکله د پاچا په حضور کې ښکاره نه شي. دا حکم دې د فارس او ماد په قوانینو کې ولیکل شي، ترڅو هغه هېڅکله بدل نه شي. همدارنګه پاچا دې د هغې ملکې مقام یوې بلې ښځې ته چې د هغې څخه دېره ښه وي، ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther1_verse_19.mp3', '', 1761754199, 1761754199),
(42550, 'Esther 1:20', 'Esther', 1, 20, 'نو کله چې د پاچا فرمان د هغه په ټولې پراخې امپراتورۍ کې اعلان شي، هغه وخت به ټولې ښځې خپلو مېړونو ته که هغه شتمن وي یا غریب، درناوی کوي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther1_verse_20.mp3', '', 1761754199, 1761754199),
(42551, 'Esther 1:21', 'Esther', 1, 21, 'په دې مشوره باندې پاچا او د هغه مامورین خوشحاله شول، نو پاچا هماغسې وکړل لکه څنګه چې مموکان وړاندیز کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther1_verse_21.mp3', '', 1761754199, 1761754199),
(42552, 'Esther 1:22', 'Esther', 1, 22, 'هغه د خپلې امپراتورۍ هر ولایت ته د هغوی په خپل خط او هر قوم ته په خپله ژبه پیغامونه واستول چې د هغې له مخې باید مېړونه د کورنۍ مشران وي او د خپلو خلکو په ژبه دې خبرې وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/esther1_verse_22.mp3', '', 1761754199, 1761754199),
(42553, 'Genesis 10:1', 'Genesis', 10, 1, 'دا د نوح د زامنو حام، سام او یافت اولاده ده چې د سېلاب څخه وروسته زېږېدلې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis10_verse_1.mp3', '', 1761754199, 1761754199),
(42554, 'Genesis 10:2', 'Genesis', 10, 2, 'د یافت زامن: جومر، ماجوج، مادای، یاوان، توبال، ماشک او تیراس.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis10_verse_2.mp3', '', 1761754199, 1761754199),
(42555, 'Genesis 10:3', 'Genesis', 10, 3, 'د جومر زامن: آشکناز، ریفات او توجرمه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis10_verse_3.mp3', '', 1761754199, 1761754199),
(42556, 'Genesis 10:4', 'Genesis', 10, 4, 'د یاوان زامن: الیشه، ترشیش، کتیان او رودانیان.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis10_verse_4.mp3', '', 1761754199, 1761754199),
(42557, 'Genesis 10:5', 'Genesis', 10, 5, 'دا د هغو خلکو نیکونه وو چې د بحیرې په غاړه او په جزیرو کې اوسېدل. دا ټوله د یافت اولاده وه چې خپلې ژبې، خپلې قبیلې او خپلې ځمکې یې درلودلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis10_verse_5.mp3', '', 1761754199, 1761754199),
